import type { Meta, StoryObj } from "@storybook/vue3";
import { h } from "vue";
import { KozmosListbox } from "../../index";

/**
 * Vue's Listbox: the stories React's has, with the same names and args,
 * each inside the KozmosThemeProvider the Storybook's decorator gives every
 * story. test/parity draws each of React's in both and holds Vue's render to
 * React's. Generated by `port Listbox`.
 */
type Args = Record<string, unknown>;
const SLOTS = ["children"];

const options = [
  { value: "nearby", label: "Nearby", description: "Closest locations first" },
  { value: "popular", label: "Popular", description: "Highest engagement" },
  { value: "recent", label: "Recent", description: "Newest activity" },
];

// GAP-192: MAP-64's Map Content type picker, its types under their families.
// Given in any order: the groups come in the order they first appear. Three,
// so the list shows them all at its 16rem.
const contentTypes = [
  { value: "office-desk", label: "Office Desk", group: "Interior Asset" },
  { value: "reception-desk", label: "Reception Desk", group: "POI" },
  { value: "hot-desk", label: "Hot Desk", group: "Interior Asset" },
];

const meta: Meta<Args> = {
  title: "Vue/Core/Inputs/Listbox",
  component: KozmosListbox,
  args: { "aria-label": "Sort locations" },
  parameters: { layout: "centered" },
  // React's node props are Vue's slots: `children` the default slot, the
  // rest slots of their own names, each drawing its arg's text.
  render: (args) => ({
    setup: () => () => {
      const props: Args = {};
      const slots: Record<string, () => string> = {};
      for (const [key, value] of Object.entries(args)) {
        if (!SLOTS.includes(key)) props[key] = value;
        else if (value !== undefined && value !== null)
          slots[key === "children" ? "default" : key] = () => String(value);
      }
      return h(KozmosListbox, props, slots);
    },
  }),
};

export default meta;
type Story = StoryObj<Args>;

export const Single: Story = {
  args: {
    defaultValue: "nearby",
    options,
  },
};

export const Multiple: Story = {
  args: {
    multiple: true,
    defaultValue: ["nearby", "recent"],
    options,
  },
};

/** Options under their groups (GAP-192); the arrow keys skip the labels. */
export const Grouped: Story = {
  args: {
    "aria-label": "Content type",
    defaultValue: "hot-desk",
    options: contentTypes,
  },
};

/**
 * An option with no group (Lift) comes first, unlabelled, before every
 * group, so it never reads as part of the group above it (GAP-192).
 */
export const GroupedAndUngrouped: Story = {
  args: {
    "aria-label": "Content type",
    options: [
      {
        value: "office-desk",
        label: "Office Desk",
        group: "Interior Asset",
      },
      {
        value: "lift",
        label: "Lift",
      },
      {
        value: "reception-desk",
        label: "Reception Desk",
        group: "POI",
      },
    ],
  },
};
